"use strict";var units={},unitList="px,cm,mm,in,pt,pc,em,ex,ch,rem,vw,vh,deg,vmin,vmax".split(",");function f(n,i){return i+n}for(var i=0;i<unitList.length;i++){var unit=unitList[i];units[unit]=f.bind(null,unit)}units.inch=function(n){return n+"in"},units.pct=function(n){return n+"%"},exports.addon=function(n){n.assign(n,units),n.units=units};